import { readFileSync } from "node:fs";
import { join } from "node:path";
import { expect, test } from "./backend";

const output = process.env.EXPOSED_CONTRACT_OUTPUT_DIR;
if (!output) throw new Error("Missing fresh Rust HTTP response directory");
const expected: Record<string, {
  display: string[];
  declared_totals: {
    current_term: { amount: string | null; declaration_count: number; incomplete: boolean };
    historical: { amount: string | null; declaration_count: number; incomplete: boolean };
  };
}> = JSON.parse(readFileSync(new URL("../../contracts/declared-totals-v1/expected.json", import.meta.url), "utf8"));
// These are actual Axum response bodies, written only after Rust's baseline assertions pass.
const responses: Record<string, string> = Object.fromEntries(
  Object.keys(expected).map((id) => [id, readFileSync(join(output, `${id}.json`), "utf8")]),
);

for (const [id, contract] of Object.entries(expected)) {
  test(`real backend declared GBP contract renders member ${id}`, async ({ backend, page }) => {
    await backend.route(`**/api/members/${id}`, (route) => route.fulfill({
      body: responses[id], contentType: "application/json",
    }));
    await page.goto(`/members/${id}`);
    await expect(page.locator(".member-total")).toHaveText(contract.display);
    await expect(page.locator(".member-earnings-totals h2").first()).toHaveText("Declared amounts this parliamentary term");
    await expect(page.locator(".member-earnings-totals h2").last()).toContainText("Historical declared amounts");
    for (const [index, period] of [contract.declared_totals.current_term, contract.declared_totals.historical].entries()) {
      if (period.amount !== null && period.declaration_count > 0) {
        const figure = page.locator(".member-total").nth(index);
        await expect(figure).toHaveAttribute("aria-label", index === 0
          ? "Declared amounts this parliamentary term in GBP"
          : "Historical declared amounts in GBP");
        if (period.incomplete) await expect(figure).toHaveAttribute("title", "Known GBP amounts only. Some amounts unavailable.");
        else await expect(figure).not.toHaveAttribute("title");
      }
    }
  });
}

test("authoritative headlines survive contradictory declarations", async ({ backend, page }) => {
  const body = JSON.parse(responses["7001"]);
  body.declarations = [];
  await backend.route("**/api/members/7001", (route) => route.fulfill({ json: body }));
  await page.goto("/members/7001");
  await expect(page.locator(".member-total")).toHaveText(expected["7001"].display);
});

const corruptions: [string, (summary: Record<string, any>) => void][] = [
  ["missing declared totals", (summary) => { delete summary.declared_totals; }],
  ["missing amount", (summary) => { delete summary.declared_totals.current_term.amount; }],
  ["missing period", (summary) => { delete summary.declared_totals.historical; }],
  ["invalid amount", (summary) => { summary.declared_totals.historical.amount = 333; }],
  ["invalid count", (summary) => { summary.declared_totals.historical.declaration_count = -1; }],
  ["missing count", (summary) => { delete summary.declared_totals.current_term.declaration_count; }],
  ["invalid boolean", (summary) => { summary.declared_totals.current_term.incomplete = "false"; }],
  ["missing boolean", (summary) => { delete summary.declared_totals.historical.incomplete; }],
  ["null start", (summary) => { summary.declared_totals.current_term_start = null; }],
  ["invalid start", (summary) => { summary.declared_totals.current_term_start = "not a date"; }],
  ["missing start", (summary) => { delete summary.declared_totals.current_term_start; }],
];
for (const [name, corrupt] of corruptions) {
  test(`mandatory headline fields fail closed: ${name}`, async ({ backend, page }) => {
    const body = JSON.parse(responses["7001"]);
    corrupt(body.summary);
    await backend.route("**/api/members/7001", (route) => route.fulfill({ json: body }));
    await page.goto("/members/7001");
    await expect(page.getByText("Details returned an unexpected response. Try again.")).toBeVisible();
    await expect(page.locator(".member-total")).toHaveCount(0);
  });
}
