          --health-timeout 5s
          --health-retries 5
    env:
      DATABASE_URL: REDACTED      CARGO_PROFILE_DEV_DEBUG: '0'
      PLAYWRIGHT_BROWSERS_PATH: '0'
    steps:
      - uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1
        with:
          fetch-depth: 0
      - name: Materialize target-branch financial baseline
        env:
          BASE_SHA: ${{ github.event.pull_request.base.sha }}
        shell: bash
        run: |
          set -euo pipefail
          fixture=contracts/declared-totals-v1/fixture.sql
          expected=contracts/declared-totals-v1/expected.json
          has_fixture=false
